683	    @Transactional
684	    @Override
685	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
686	        Owner owner = this.clinicService.findOwnerById(ownerId);
687	        if (owner == null) {
688	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
689	        }
690	        this.clinicService.deleteOwner(owner);
691	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
692	    }
693	
694	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
695	    @Override
696	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
697	        Owner owner = this.clinicService.findOwnerById(ownerId);
698	        if (owner == null) {
699	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
700	        }
701	        HttpHeaders headers = new HttpHeaders();
702	        Pet pet = petMapper.toPet(petFieldsDto);
703	        owner.setId(ownerId);
704	        pet.setOwner(owner);
705	        pet.getType().setName(null);
706	        this.clinicService.savePet(pet);
707	        PetDto petDto = petMapper.toPetDto(pet);
708	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
709	            .buildAndExpand(pet.getId()).toUri());
710	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
711	    }
712	
713	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
714	    @Override
715	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
716	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
717	        if (currentOwner != null) {
718	            Pet currentPet = this.clinicService.findPetById(petId);
719	            if (currentPet != null) {
720	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
721	                currentPet.setName(petFieldsDto.getName());
722	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
723	                this.clinicService.savePet(currentPet);
724	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
725	            }
726	        }
727	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
728	    }
729	
730	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
731	    @Override
732	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
733	        HttpHeaders headers = new HttpHeaders();
734	        Visit visit = visitMapper.toVisit(visitFieldsDto);
735	        Pet pet = new Pet();
736	        pet.setId(petId);
737	        visit.setPet(pet);
738	        this.clinicService.saveVisit(visit);
739	        VisitDto visitDto = visitMapper.toVisitDto(visit);
740	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
741	            .buildAndExpand(visit.getId()).toUri());
742	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
743	    }
744	
745	
746	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
747	    @Override
748	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
749	        Owner owner = this.clinicService.findOwnerById(ownerId);
750	        if (owner != null) {
751	            Pet pet = owner.getPet(petId);
752	            if (pet != null) {
753	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
754	            }
755	        }
756	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
757	    }
